/// `size_prefixed_root_as_tdm_unchecked`.
pub fn size_prefixed_root_as_tdm(buf: &[u8]) -> Result<TDM<'_>, ::flatbuffers::InvalidFlatbuffer> {
  ::flatbuffers::size_prefixed_root::<TDM>(buf)
}
#[inline]
